-- GENERATED by `wfj generate` from data/quest/quest-0095.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [95034] = { "Il debito", "Parla con Lumina Windsinger alla ⟦Sepulcher=Mausolea⟧.", "Credo che tu debba sapere che non sono stati davvero gli gnoll ad attaccarci sulla strada.\n\nIn realtà ci ha attaccati una creatura gigantesca, simile a un lupo, che ora so chiamarsi \"worgen\". Ha fatto fuori le nostre guardie ed è venuta verso di me, ma Banon si è gettato sul suo cammino. Sono riuscita a lanciare un incantesimo che ha spaventato la creatura e l'ha messa in fuga, ma Banon era già stato morso gravemente. Insisteva perché lo lasciassi lì, ma mi sono rifiutata.\n\nStavamo tornando qui zoppicando quando ci hanno trovati gli gnoll. Ciò che è successo dopo è stato terrificante...", nil, "Ora capisci. Allo stremo delle forze, dopo essere stato trafitto da una dozzina di lame gnoll, si è sollevato per colpirmi. In quell'ultimo istante i nostri sguardi si sono incrociati, e ho capito che sapeva ancora chi era e che mi riconosceva. Sapeva cosa stava succedendo, ma non aveva alcun controllo su se stesso. Quella è stata la parte peggiore.\n\nSe una cosa simile è possibile, vedrò morta la creatura che lo ha condannato, così che non possa mai più infliggere quest'orrore a un altro essere vivente. Lo giuro sul cielo sopra di noi.", 0x0ff7705c, 0x84784026, 0xdc6412d7, nil, 0xb4f8e463, "...m." },
  [95036] = { "Una lama baciata dalla luna", "Parla con Trevan Rol alla ⟦Sepulcher=Mausolea⟧ e portagli i materiali che gli servono.", "Trevan mi dice che i worgen sono una grave minaccia per gli abitanti della ⟦Silverpine Forest=Selva Pinargento⟧. Nonostante la loro forza e resistenza possono essere uccisi, ma ce n'è uno in particolare che, per una magia sconosciuta, sembra non restare mai morto.\n\nÈ quello che ci ha attaccati. È noto come Old Fire-Eye ed è il più grosso e il più crudele della sua specie. Per abbatterlo ci servirà un'arma speciale.\n\nParla con Trevan: ti darà un elenco di ciò che serve per forgiare un'arma simile.", "Affidati alla Luce perché guidi la tua lama. Ma la Luce ha bisogno di una buona lama da guidare.", "Ora che abbiamo i materiali che ci servono, ci manca solo un fabbro che forgi la lama per noi. E credo di conoscere proprio il fabbro giusto.", 0xe7da37a4, 0x4585e62b, 0xb4f5a29b, 0x1c7078a4, 0xf4085685, "....." },
  [95041] = { "Accumulatori di dati", "Raccogli 7 Gnomeregan Archival Data nei dintorni di Gnomeregan, poi consegnali a Jemma Quikswitch a ⟦Ironforge=Forgiardente⟧.", "Prima di fuggire da Gnomeregan ho fatto una copia cartacea degli archivi di famiglia. Equazioni di campo arcanotecniche, progetti di scafi di sottomarini della Seconda Guerra, la ricetta del chili di nonna Quikswitch... le nostre più grandi conquiste sono in quei file.\n\nSolo una volta a ⟦Ironforge=Forgiardente⟧ ho scoperto un buco nello zaino! Mancano diverse schede perforate e, senza di loro, i dati sono troppo confusi per recuperarli.\n\nLe schede devono essere sepolte nella neve, da qualche parte fuori da Gnomeregan. Potresti trovarle? Lo so, è un tentativo disperato...", "Come procede il recupero dei dati?", "Queste schede sembrano un po' umide... ma posso lavorarci! Grazie, {name}!", 0x2ec708ec, 0xdde3bae7, 0xd738032b, 0x4bbba72e, 0x87fa01c3, "....." },
  [95042] = { "Alla ricerca della Gemma Kor", "Porta una Gemma Kor a Ulric Frostveil a ⟦Ashenvale=Valtetra⟧.", "<Un/Una> <paladino/paladina> dei Reietti... qui a ⟦Ashenvale=Valtetra⟧? Divertente.\n\nQuindi cerchi una Gemma Kor? Non mi sorprende: a volte i paladini dell'⟦Alliance=Alleanza⟧ le usano per potenziare armi e strumenti magici. Perché <un/una> <paladino/paladina> <caduto/caduta> come te dovrebbe essere diverso?\n\nSe desideri davvero una di queste gemme, devi andare a nord, nelle rovine note come ⟦Blackfathom Deeps=Abissi di Fondocupo⟧. I naga che usano ancora le gemme si trovano là sotto. Non andare da sol<o/a>, {class}.", "Le gemme Kor possono servire a grandi atti di malvagità. Non sta a me giudicare se le tue intenzioni sono pure. A me non importa.", "Avrai senz'altro notato la corruzione che permea questa gemma. Per i tuoi scopi, la magia necessaria a dissipare il male che le streghe naga vi hanno infuso è piuttosto semplice. Un vero peccato: si potrebbe imparare molto da poteri simili.\n\nNon è che saresti dispost<o/a> ad abbandonare qualunque missione ti abbia spinto a cercare questa gemma, e a vendermela invece? Potrebbe rivelarsi preziosa per le mie... ricerche accademiche.", 0x5d353131, 0x653f65b8, 0x34bb9815, 0x3e8b8507, 0x8c1b448d, "....." },
  [95065] = { "È ora di pescare", "Porta $N1 ⟦Shiny Bauble=Esca Lucente⟧ e $N2 Nightcrawlers a Gilbert Gray, al porto di ⟦Stormwind=Roccavento⟧.", "Che vista... Il meglio che un vecchio possa chiedere.\n\nI pesci abboccano eccome, adesso, ma mi è rimasta solo l'ultima esca. Non è che hai con te dell'attrezzatura da pesca in più? Ma certo che no, perdonami. Mi entusiasmo così tanto all'idea di lanciare un'altra lenza che non mi è venuto in mente che forse sono uno dei pochi a portarsi dietro l'attrezzatura ovunque vada.\n\nPotresti aiutarmi a rifornirmi? Catherine Leland ha un assortimento di articoli da pesca appena a ovest del ⟦Trade District=Quartiere del Commercio⟧, lungo i canali. Dille che ti manda il vecchio Gray.", "Hai preso l'attrezzatura da pesca?", "Tempismo perfetto! Ne ho preso uno grosso con l'ultima esca. Finora è una gran giornata. Qui abboccano davvero!\n\nFacciamo così: visto che sei stat<o/a> così gentile da tenere in attività questo vecchio, che ne dici di qualche pesce per il viaggio?", 0x50ff1618, 0x1ca3ae56, 0x4f6c7d2d, 0x630eca56, 0x7cc547b8, "....." },
  [95111] = { "Un talento sottovalutato", "Parla con Ott e chiedigli di forgiare la tua lama.", "Al ⟦Tarren Mill=Mulino di Tarren⟧ c'è un fabbro d'armi di nome Ott. A detta di tutti è un fabbro qualunque, che vende lame semplici ai viaggiatori. Io stesso ho comprato una spada da lui e, quando qualche tempo dopo l'ho portata a Sepulcra per la manutenzione, i fabbri di lì sono rimasti sorpresi dalla sua qualità. Pensavano che venisse da un celebre mastro fabbro, ma no: era soltanto Ott.\n\nVorrei dare a questo orco l'occasione di fare qualcosa di davvero speciale. Porta i materiali a Ott, al ⟦Tarren Mill=Mulino di Tarren⟧, e offrigli la commissione.", "Ti serve una lama, {class}?", "Interessante. Non credo che qualcuno mi abbia mai chiesto di eseguire una commissione su misura. Di solito faccio solo armi umili e funzionali, a modo mio. Non è granché, ma è un lavoro onesto e non cerco riconoscimenti né gloria.\n\nSono felice di provarci, ma perché sei venut<o/a> da me per questo? A ⟦Undercity=Sepulcra⟧ ci sono tanti fabbri che accetterebbero lavori su misura come questo.", 0x2c5a8af0, 0x57d2ed34, 0x9137acf7, 0x45d644e4, 0xc6b81f00, "....." },
  [95125] = { "Il capolavoro di Ott", "Guarda Ott mentre forgia la tua lama.", "Sono materiali davvero pregiati, {class}. Mi onori lasciandomi forgiare questa lama per te, e spero solo di essere all'altezza delle tue aspettative.\n\nTi prego, fatti indietro, così posso cominciare la forgiatura.", nil, "Questa lama è il mio lavoro migliore e spero che ti serva bene nei tuoi viaggi. Grazie ancora per questa occasione.\n\nAka'Magosh, amic<o/a>.", 0x2af2ae36, 0xa5330aaf, 0xa0a0368f, nil, 0xee452c14, "...m." },
  [95126] = { "La Moonsilver Blade", "Porta Ott's Masterwork a Trevan Rol nella ⟦Silverpine Forest=Selva Pinargento⟧.", "Ecco la lama. Hai detto che ti ha mandato un paladino di nome Trevan? Quando lo rivedrai, ringrazialo da parte mia per questa occasione. Va' con onore, amic<o/a>.", "Ott è riuscito a portare a termine la commissione?", "<Trevan prende la lama e la esamina con cura.>\n\nAndrà benissimo, {name}. Sapevo che Ott era capace di creare qualcosa di davvero grande.\n\nOra non resta che uccidere quella bestia. Parla con Lumina quando sei pront<o/a>.", 0x774c6075, 0xb9d5e27a, 0xac0b5a01, 0xaf39b5e9, 0x469d97a1, "....." },
  [95140] = { nil, "Usa la Moonsilver Blade per distruggere Old Fire-Eye nella ⟦Silverpine Forest=Selva Pinargento⟧.", "Vedo che ora hai la tua arma, {class}. Prego che non ti tradisca.\n\nLa gente del posto dice che Old Fire-Eye caccia in un'ampia zona a sud di qui e che di solito lo si trova vicino ai cancelli di Gilneas. Trovalo e usa la tua nuova lama per farla finita con lui. Quando avrai finito, torna e avrai la gratitudine dei Windshaper.", "È fatta? La bestia è morta?", "Grazie, {name}. Ora Banon può riposare in pace.\n\nSe me lo permetti, credo di poter infondere nella tua lama, appena bagnata di sangue, una piccola parte della magia del mio popolo.\n\n<Gli occhi di Lumina Windsinger cominciano a brillare di un azzurro vivido mentre tocca la lama insanguinata che hai in mano.>\n\nÈ fatto. È poca cosa, e difficilmente potrei migliorare una lama così magnifica. In ogni caso, pregherò i venti perché ti serva bene, {class}.", 0x1db24010, 0xee598827, 0x2f1bb8e0, 0x95a43f2e, 0xb76eccca, "e...." },
  [95161] = { "Ricorda che ti voglio bene", "Consegna la Blood-Stained Letter ad Avette Fellwood a ⟦Duskwood=Boscovespro⟧.", "Se cerchi Jeremy Heartweaver, la cosa migliore è parlare con la sua nuova madre adottiva, Avette Fellwood, giù a ⟦Duskwood=Boscovespro⟧. Una donna dolce. Probabilmente le serve un altro paio di mani per il suo lavoro, ma è sempre meglio che restare all'orfanotrofio.\n\nSe vedi il piccolo Jeremy, digli che pensiamo tutti a lui, d'accordo?", "Sì? Di cosa hai bisogno?", "Oh, no...\n\nÈ gentile da parte tua portarmela, ma non credo che Jeremy sia pronto a vederla. La direttrice Nightingale ha detto che il mio piccolo Jeremy non parla più dall'attacco a Lordaeron, e non intendo forzarlo adesso. Mostrargliela gli causerebbe solo altro dolore.\n\nNon guardarmi così. Non gli nasconderò il suo passato, ma ha bisogno di tempo per guarire. Gliela darò quando sarà più grande. Grazie di essere passat<o/a>, ma credo sia ora che tu vada.", 0x920a601f, 0xa5aac85c, 0xab5e3e2b, 0x664e4a5c, 0xbb9d2166, "....." },
  [95189] = { nil, "Riporta il Crest of Lordaeron a Lady Dena Kennedy a ⟦Stormwind City=Roccavento⟧.", "<Uno stemma consunto che raffigura il simbolo di Lordaeron. Con così poche reliquie rimaste dopo la caduta del regno, qualcuno a ⟦Stormwind=Roccavento⟧ sarebbe molto ansioso di metterci le mani sopra.>", nil, nil, 0x98ec1516, 0xea3f7a39, 0x6f2a4873, nil, nil, "e..mm" },
  [95195] = { nil, "Raccogli $N1 Bloodied Insignia e portale al generale Marcus Jonathan a ⟦Stormwind City=Roccavento⟧.", "<La vecchia insegna dell'⟦Alliance=Alleanza⟧ sembra essere appartenuta a un soldato di Lordaeron. Queste rovine sono probabilmente piene di medaglie simili, che i parenti ancora in vita sarebbero grati di riavere.>", "Sembri portare un pesante fardello, {name}. Di che si tratta?", "Il tuo istinto di portarmele non era infondato. Quando Lordaeron cadde sotto il Flagello, molti fuggirono per rifugiarsi qui a ⟦Stormwind=Roccavento⟧. Probabilmente ne restano pochi che possano reclamare di persona queste insegne.\n\nIl tuo servizio a ⟦Stormwind=Roccavento⟧ merita un encomio, {name}. Comincerò subito a consegnare questi pegni ai parenti più stretti.", 0xfb70dfc5, 0xf9dfef5a, 0x2c958367, 0x3d6daf5e, 0x351f4fdf, "e...." },
  [95204] = { nil, "Porta il Crest of Lordaeron a Oran Snakewrithe a ⟦Undercity=Sepulcra⟧.", "<Uno stemma consunto che raffigura il simbolo di Lordaeron. Con così poche reliquie rimaste dopo la caduta del regno, qualcuno a ⟦Undercity=Sepulcra⟧ sarebbe molto ansioso di metterci le mani sopra.>", "Che cos'hai lì, {class}? Un bocconcino gustoso?", "<Oran morde lo stemma per accertarne l'autenticità.>\n\nGuarda un po'. Un'autentica reliquia della nostra patria. Quasi intatta, per giunta. Con questa dovremo stare molto attenti.\n\nGrazie per averci aiutato a restaurare la nostra storia, {class}. Mi assicurerò che ne abbiamo cura.", 0x98ec1516, 0x937c7b4b, 0x992e7722, 0x059931e7, 0xc46da411, "e...." },
  [95212] = { "Sulle selle non si risparmia", "Raccogli 6 Pristine Leopard Pelt e consegnale alla ⟦Amberstill Ranch=Tenuta di Ambraquieta⟧.", "Ci stiamo preparando a mandare una squadra di arieti a rinforzare la spedizione di Alterac, ma abbiamo finito il materiale per fare le selle.\n\nRaccogli le pelli dei leopardi più grossi e feroci a est e portamele. Lassù fa un freddo pungente, e le nostre truppe meritano solo le pelli migliori per tenersi al caldo!", "Hai l'aria infreddolita, {class}. Come va la caccia?", "Queste pelli diventeranno selle eccellenti. Hai reso onore all'⟦Alliance=Alleanza⟧, {class}!", 0x07df31f7, 0x270babaf, 0xb5c3ab85, 0x545929d0, 0xcdcfccf7, "....." },
  [95213] = { nil, "Porta l'Empty Powder Keg al capocava Thesten, alla ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧.", "Sul barile c'è un timbro:\n\nPOLVERE ESPLOSIVA - PERICOLO - NON MANEGGIARE - PERICOLO - SOLO CON AUTORIZZAZIONE DEL CAPOCAVA - PERICOLO\n\nHai la brutta sensazione che i trogg non dovrebbero averla. Sarebbe meglio avvisare la cava al più presto.", "Che cos'hai lì?", "<Il nano impallidisce quando vede il barile vuoto.>\n\n...Dove l'hai trovato?", 0x8848eca5, 0xd56ef55e, 0xf1f411df, 0xac2369a3, 0x28899f23, "e...." },
  [95214] = { nil, "Recupera $N1 Stolen Blasting Powder dai trogg a est della ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧, poi torna dal capocava Thesten.", "Questo barile conteneva abbastanza polvere da trasformare la sala del trono di re Magni in un cortile a cielo aperto. Dobbiamo recuperarla dai trogg prima che capiscano come accenderla.", "Spero che tu abbia buone notizie per me.", nil, 0x8848eca5, 0x4fe59366, 0xcc857a5c, 0xb50481e8, nil, "e...m" },
  [95216] = { "La nuova piaga", "Preleva la Highly Toxic Strain da Witherfang nelle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧ per Theodore Griffs, a ⟦Undercity=Sepulcra⟧.", "Benvenut<o/a> nell'organo più vitale di ⟦Undercity=Sepulcra⟧: l'Apothecarium! Qui sperimentiamo sui più virulenti tra gli esemplari esotici di Azeroth.\n\nSono di buon umore, perciò ti metterò a parte della mia ultima indagine. Pare che un artropode particolarmente velenoso si aggiri tra le rovine sopra la nostra bella città. Si dice che le sue tossine corrodano persino la carne dei non morti. Che cosa elettrizzante!\n\nVoglio verificare queste voci. Se dovessi trovarti a deperire per il suo morso, mi piacerebbe tanto averne un campione.", "Qualunque sciocco ti dirà che il metodo di trasmissione più efficace passerà sempre per il sangue.\n\nDevo vedere questo ceppo con i miei occhi!", "L'hai ucciso??\n\nHmpf. Per tua fortuna, questo icore dovrebbe bastare per ricostruirne le proprietà. Non ti conviene metterti contro la Royal Apothecary Society.\n\nSparisci dalla mia vista!", 0xbf7a7e24, 0xec263960, 0x9214d563, 0x5c8c63f0, 0x8f9e0d7b, "....." },
  [95217] = { "Il fabbro della cava", "Raccogli 12 Lingotto di Rame e 4 Toughened Boar Hide e consegnali a Frast Dokner.", "Quindi vuoi imparare il mestiere del fabbro? Forse possiamo aiutarci a vicenda.\n\nIl carico di rifornimenti è in ritardo e mi servono materiali per qualche riparazione all'accampamento. Se mi procuri quello che mi serve, ti insegnerò alcune delle mie tecniche. Ti sembra giusto?", "Non battere la fiacca, {name}. Fare il fabbro non è roba da pigri!", "Sei una persona piena di risorse, {name}.\n\nOra ascoltami bene: non ho intenzione di ripetermi!", 0xcf9ba453, 0x56fdeb4f, 0xd3803ca1, 0x8461c8b8, 0x9e396b99, "....." },
  [95250] = { "Creature abominevoli", "Recupera la Head of the Baron nelle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧ e riportala al capitano Truman.", "Che vuoi, {race}? Non vedi che c'è una guerra da vincere?\n\nIl mio padrone si è già lanciato nella mischia e mi ha ordinato di restare al mio posto. Però è passato parecchio tempo.\n\nDubito che sopravvivresti dieci minuti in combattimento, ma se serve a tenere occupata la tua mente semplice, perché non vai a cercare il gran maresciallo? È l'eroe più alto e statuario su cui tu abbia mai posato gli occhi. Lo riconoscerai quando lo vedrai.", nil, nil, 0x83266151, 0xb8e0ac06, 0x0f67af09, nil, nil, "...mm" },
  [95314] = { "Quell'elisir verde di Shadowvale", "Raccogli $N1 Bottle of Whispering Elixir a Shadowvale, poi torna da Carolai Anise a Brill.", "Prima dell'invasione del Flagello, l'isolato villaggio di Shadowvale era noto per il suo Whispering Elixir. Distillato da erbe che si trovano solo a Tyr's Fall, l'elisir era ricercato da speziali, mistici e avvelenatori, anche dopo essere stato bandito in città.\n\nHo ricevuto richieste da diversi compratori ansiosi di mettere le mani su un po' di elisir. Raggiungi le rovine di Shadowvale, nel profondo della Whispering Forest, a ovest. Offro un compenso considerevole se riesci a recuperarne qualche bottiglia per me.", "Confido che tu non ti sia pers<o/a>?", "Dici che a Shadowvale c'è del male? Ammetto che non mi sorprende. La gente della foresta era un tipo strano e non amava i visitatori. Alcuni credono che la Whispering Forest stessa sia maledetta e che l'elisir distillato dalle sue radici porti con sé la stessa maledizione...\n\n...ma basta con superstizioni e dicerie, {name}. Grazie per gli elisir. Ecco, prendi questo come pagamento.", 0x62c6b7bf, 0xff6777a1, 0x5740e013, 0x46ba8900, 0x23664c51, "....." },
  [95350] = { "Benvenuti su Azeroth", nil, nil, nil, nil, 0x2f003d6f, nil, nil, nil, nil, ".mmmm" },
  [95494] = { "Orgoglio ferito e pelli di leone", "Raccogli 6 Savannah Lion Hide dalle Savannah Matriarch e dai Savannah Patriarch nelle ⟦Barrens=Savane⟧.", "Mi serve qualcuno con un braccio forte per la spada e un po' di tempo libero, che mi aiuti a raccogliere delle pelli di leone. Mi brucia l'orgoglio chiedere un aiuto simile a un estraneo, ma di recente mi sono ferito a una gamba. Finché non guarisco non sono in condizione di andare a caccia, ma ho degli impegni da rispettare.\n\nDi solito i più grossi di questa zona hanno le pelli migliori, quindi comincia da quelli.", "Come va la caccia?", nil, 0x5b2ff02d, 0xce49bfcd, 0x5cce729a, 0xe02b27bb, nil, "....m" },
  [95999] = { nil, nil, nil, "Che cos'hai lì, {race}?", nil, nil, nil, nil, 0x46dc827d, nil, "mmm.m" },
})
